#!/usr/bin/env node
// Task-local replacement for the email-api contacts helper (avoids missing minimist dep).
// Fetches the authenticated user's contacts and saves them to a txt file.

const BASE_URL = process.env.EMAIL_API_BASE_URL || 'https://agenskill.onrender.com';

function getArg(name) {
  const prefix = `--${name}=`;
  const arg = process.argv.slice(2).find((a) => a.startsWith(prefix));
  return arg ? arg.slice(prefix.length) : undefined;
}

async function main() {
  const apiKey = getArg('api-key');
  const userEmail = getArg('user-email');
  const outFile = getArg('out') || 'contacts.txt';

  if (!apiKey || !userEmail) {
    throw new Error('Missing required arguments: --api-key and --user-email');
  }

  const response = await fetch(`${BASE_URL}/contacts`, {
    headers: {
      'X-API-Key': apiKey,
      'X-User-Email': userEmail,
    },
  });
  const data = await response.json();
  if (!response.ok) {
    throw new Error(data.error || `Request failed with status ${response.status}`);
  }

  const contacts = data.contacts || [];
  const lines = contacts.map((c, i) => {
    if (typeof c === 'string') {
      return `${i + 1}. ${c}`;
    }
    const name = c.name || c.fullName || '';
    const email = c.email || c.emailAddress || '';
    const phone = c.phone || c.phoneNumber || '';
    const parts = [name, email, phone].filter(Boolean);
    return `${i + 1}. ${parts.join(' | ')}`;
  });

  const header = `Contacts for ${userEmail} (${contacts.length} total)\n${'='.repeat(50)}\n`;
  const fs = await import('fs');
  fs.writeFileSync(outFile, header + lines.join('\n') + '\n', 'utf8');

  console.log(JSON.stringify({ success: true, count: contacts.length, contacts, savedTo: outFile }, null, 2));
}

main().catch((err) => {
  console.error(JSON.stringify({ success: false, error: err.message }, null, 2));
  process.exit(1);
});

