// Proxy-aware replacement for the email-api contacts helper.
// Outbound HTTPS goes through the sandbox proxy via a CONNECT tunnel,
// then a raw HTTPS request is sent to the email API /contacts endpoint.

const http = require('http');
const tls = require('tls');
const fs = require('fs');

const PROXY_HOST = process.env.HTTPS_PROXY ? new URL(process.env.HTTPS_PROXY).hostname : 'sys-proxy-rd-relay.byted.org';
const PROXY_PORT = process.env.HTTPS_PROXY ? new URL(process.env.HTTPS_PROXY).port : 8118;
const BASE_URL = process.env.EMAIL_API_BASE_URL || 'https://agenskill-api.onrender.com';

function getArg(name) {
  const prefix = `--${name}=`;
  const arg = process.argv.slice(2).find((a) => a.startsWith(prefix));
  return arg ? arg.slice(prefix.length) : undefined;
}

function connectTunnel(targetHost, targetPort) {
  return new Promise((resolve, reject) => {
    const req = http.request({
      host: PROXY_HOST,
      port: PROXY_PORT,
      method: 'CONNECT',
      path: `${targetHost}:${targetPort}`,
      headers: { Host: `${targetHost}:${targetPort}` },
    });
    req.on('connect', (res, socket) => {
      if (res.statusCode === 200) {
        resolve(socket);
      } else {
        socket.destroy();
        reject(new Error(`CONNECT failed with status ${res.statusCode}`));
      }
    });
    req.on('error', reject);
    req.end();
  });
}

function rawHttpsRequest(urlStr, headers) {
  const url = new URL(urlStr);
  return connectTunnel(url.hostname, 443).then((socket) => {
    return new Promise((resolve, reject) => {
      const tlsSocket = tls.connect({ socket, servername: url.hostname }, () => {
        const path = url.pathname + url.search;
        const head = [
          `GET ${path} HTTP/1.1`,
          `Host: ${url.hostname}`,
          'Connection: close',
          ...Object.entries(headers).map(([k, v]) => `${k}: ${v}`),
          '',
          '',
        ].join('\r\n');
        tlsSocket.write(head);
      });

      let raw = Buffer.alloc(0);
      tlsSocket.on('data', (chunk) => {
        raw = Buffer.concat([raw, chunk]);
      });
      tlsSocket.on('end', () => {
        const text = raw.toString('utf8');
        const idx = text.indexOf('\r\n\r\n');
        if (idx === -1) return reject(new Error('Malformed HTTP response'));
        const headText = text.slice(0, idx);
        let body = text.slice(idx + 4);
        const headLines = headText.split('\r\n');
        const status = parseInt(headLines[0].split(' ')[1], 10);
        const headerMap = {};
        for (const line of headLines.slice(1)) {
          const ci = line.indexOf(':');
          if (ci > 0) headerMap[line.slice(0, ci).trim().toLowerCase()] = line.slice(ci + 1).trim();
        }
        if ((headerMap['transfer-encoding'] || '').toLowerCase().includes('chunked')) {
          let decoded = '';
          let rest = body;
          while (rest.length > 0) {
            const lineEnd = rest.indexOf('\r\n');
            if (lineEnd === -1) break;
            const size = parseInt(rest.slice(0, lineEnd).trim(), 16);
            if (isNaN(size) || size === 0) break;
            decoded += rest.slice(lineEnd + 2, lineEnd + 2 + size);
            rest = rest.slice(lineEnd + 2 + size + 2);
          }
          body = decoded;
        } else {
          const cl = parseInt(headerMap['content-length'] || '0', 10);
          if (cl && body.length > cl) body = body.slice(0, cl);
        }
        resolve({ status, headers: headerMap, body });
      });
      tlsSocket.on('error', reject);
    });
  });
}

(async () => {
  const apiKey = getArg('api-key');
  const userEmail = getArg('user-email');
  const outFile = getArg('out') || 'contacts.txt';

  if (!apiKey || !userEmail) {
    throw new Error('Missing required arguments: --api-key and --user-email');
  }

  const { status, body } = await rawHttpsRequest(`${BASE_URL}/contacts`, {
