#!/usr/bin/env node
// Minimal DNS + connectivity diagnostics:
// 1) Send raw DNS A queries to the resolv.conf nameservers.
// 2) If addresses resolve, test TCP connect to :443.

const dgram = require('dgram');
const net = require('net');

const NAMESERVERS = ['fdbd:dc00::10:8:8:8', 'fdbd:dc00::10:8:8:9'];

function encodeName(name) {
  return name.split('.').map((label) => `${String.fromCharCode(label.length)}${label}`).join('') + '\x00';
}

function buildQuery(id, name) {
  const buf = Buffer.alloc(12);
  buf.writeUInt16BE(id, 0); // id
  buf.writeUInt16BE(0x0100, 2); // RD
  buf.writeUInt16BE(1, 4); // QDCOUNT
  const qname = Buffer.from(encodeName(name), 'binary');
  const q = Buffer.alloc(4);
  q.writeUInt16BE(1, 0); // QTYPE A
  q.writeUInt16BE(1, 2); // QCLASS IN
  return Buffer.concat([buf, qname, q]);
}

function decodeName(msg, offset) {
  const labels = [];
  let jumped = false;
  let p = offset;
  let end = offset;
  while (true) {
    const len = msg[p];
    if (len === 0) {
      if (!jumped) end = p + 1;
      break;
    }
    if ((len & 0xc0) === 0xc0) {
      if (!jumped) end = p + 2;
      p = ((len & 0x3f) << 8) | msg[p + 1];
      jumped = true;
    } else {
      labels.push(msg.slice(p + 1, p + 1 + len).toString());
      p += 1 + len;
      if (!jumped) end = p;
    }
  }
  return { name: labels.join('.'), end };
}

function queryA(nameserver, name, id) {
  return new Promise((resolve, reject) => {
    const sock = dgram.createSocket('udp6');
    const timeout = setTimeout(() => {
      sock.close();
      reject(new Error(`timeout querying ${nameserver}`));
    }, 5000);
    sock.on('message', (msg) => {
      clearTimeout(timeout);
      sock.close();
      try {
        if (msg.readUInt16BE(0) !== id) return reject(new Error('mismatched id'));
        const qdcount = msg.readUInt16BE(4);
        const ancount = msg.readUInt16BE(6);
        let p = 12;
        for (let i = 0; i < qdcount; i++) p = decodeName(msg, p).end + 4;
        const addrs = [];
        for (let i = 0; i < ancount; i++) {
          const dn = decodeName(msg, p);
          p = dn.end;
          const type = msg.readUInt16BE(p);
          const rdlength = msg.readUInt16BE(p + 8);
          const rdata = msg.slice(p + 10, p + 10 + rdlength);
          p += 10 + rdlength;
          if (type === 1 && rdlength === 4) {
            addrs.push([...rdata].join('.'));
          }
        }
        resolve({ nameserver, name, addrs, ancount });
      } catch (e) {
        reject(e);
      }
    });
    sock.on('error', (e) => {
      clearTimeout(timeout);
      reject(e);
    });
    const q = buildQuery(id, name);
    sock.send(q, 53, nameserver);
  });
}

function testTcp(host, port, family) {
  return new Promise((resolve) => {
    const sock = net.connect({ host, port, family });
    const t = setTimeout(() => {
      sock.destroy();
      resolve({ host, port, ok: false, error: 'timeout' });
    }, 5000);
    sock.on('connect', () => {
      clearTimeout(t);
      sock.destroy();
      resolve({ host, port, ok: true });
    });
    sock.on('error', (e) => {
      clearTimeout(t);
      resolve({ host, port, ok: false, error: e.code || e.message });
    });
  });
}

(async () => {
  const out = { dns: [], tcp: [] };
  const targets = ['sys-proxy-rd-relay.byted.org', 'agenskill-api.onrender.com', 'agenskill.onrender.com'];
  let id = 0x1234;
  for (const ns of NAMESERVERS) {
    for (const name of targets) {
      try {
        const r = await queryA(ns, name, id++);
        out.dns.push(r);
      } catch (e) {
        out.dns.push({ nameserver: ns, name, error: e.message });
      }
    }
  }
  const ips = new Set();
  for (const r of out.dns) {
    if (r && r.addrs) r.addrs.forEach((a) => ips.add(a));
  }
  for (const ip of ips) {
    out.tcp.push(await testTcp(ip, 443, 4));
  }
  console.log(JSON.stringify(out, null, 2));
})();
